{
  "story": "The algorithm evaluates every unique feature value as a potential split threshold. It calculates the impurity drop for each split point, selecting the value that maximizes information gain to partition the data cleanly.",
  "aha": {
    "stateId": "eval-optimal",
    "observation": "The threshold with the highest impurity reduction is chosen as the optimal split point."
  },
  "layout": {
    "preset": "card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "reason": "state.why"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "values": "state.why"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    },
    {
      "id": "prog",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.stepIndex"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Search Step",
      "options": [
        "Sort values",
        "Test threshold 2.0",
        "Test threshold 4.5",
        "Select optimal"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Threshold Search",
        "regions": [
          {
            "id": "feature-array",
            "label": "Sorted Feature Values",
            "values": ["1.0", "2.0", "3.5", "4.5", "6.0"]
          },
          {
            "id": "split-metrics",
            "label": "Impurity Scores",
            "values": ["Gini: 0.48", "Gini: 0.35", "Gini: 0.20", "Gini: 0.12", "Gini: 0.40"]
          }
        ],
        "states": [
          {
            "id": "sort-vals",
            "label": "Sort",
            "short": "Sort",
            "sentence": "Feature values are sorted in ascending order to test intervals between them.",
            "why": "Ordering makes midpoint calculations straightforward.",
            "active": ["feature-array"],
            "calloutRegion": "feature-array",
            "readouts": [
              {
                "id": "r1",
                "label": "Candidate Count",
                "value": "4"
              }
            ]
          },
          {
            "id": "test-first",
            "label": "Test 2.0",
            "short": "Test 2.0",
            "sentence": "Testing threshold at 2.0 splits the dataset into left and right subsets.",
            "why": "Evaluates Gini impurity for the resulting node groups.",
            "active": ["feature-array", "split-metrics"],
            "calloutRegion": "split-metrics",
            "readouts": [
              {
                "id": "r2",
                "label": "Current Gini",
                "value": "0.35"
              }
            ]
          },
          {
            "id": "test-opt",
            "label": "Test 4.5",
            "short": "Test 4.5",
            "sentence": "Testing threshold at 4.5 yields a significant drop in impurity.",
            "why": "Separates classes with high purity on both sides.",
            "active": ["feature-array", "split-metrics"],
            "calloutRegion": "split-metrics",
            "readouts": [
              {
                "id": "r3",
                "label": "Current Gini",
                "value": "0.12"
              }
            ]
          },
          {
            "id": "eval-optimal",
            "label": "Optimal",
            "short": "Optimal",
            "sentence": "Threshold 4.5 is selected because it produces the minimum impurity score.",
            "why": "Maximizes information gain for the decision tree node.",
            "active": ["split-metrics"],
            "calloutRegion": "split-metrics",
            "readouts": [
              {
                "id": "r4",
                "label": "Best Threshold",
                "value": "4.5"
              }
            ]
          }
        ]
      }
    ]
  }
}
